def _round_ratio(numerator, denominator, mode):
    mode = mode if mode in _ROUNDING else 'floor'
    quotient, remainder = divmod(numerator, denominator)

    if mode == 'ceil' or mode == 'ceiling':
        return quotient + (1 if remainder else 0)
    if mode == 'down':
        return quotient if numerator >= 0 or not remainder else quotient + 1
    if mode == 'half_up':
        if remainder * 2 >= denominator:
            return quotient + 1
        return quotient
    if mode == 'half_even':
        if remainder * 2 > denominator or (remainder * 2 == denominator and quotient % 2):
            return quotient + 1
        return quotient
    return quotient


def amount(event, mode):
    base = int(event['price']) * int(event.get('quantity', 1))
    discount_bp = max(0, min(10000, int(event.get('discount_bp', 0))))
    net = _round_ratio(base * (10000 - discount_bp), 10000, mode)
    tax_bp = int(event.get('tax_bp', 0))
    tax = _round_ratio(net * tax_bp, 10000, mode)
    return net + tax
